import AppKit
import Foundation

func pasteboardContainsConcealedType(_ pasteboard: NSPasteboard) -> Bool {
    let concealedTypeIdentifiers: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.sophiacom.macpass",
        "com.lastpass.LastPass",
        "net.mactypers.concealed",
    ]
    guard let types = pasteboard.types else { return false }
    return types.contains { concealedTypeIdentifiers.contains($0.rawValue) }
}

struct ClipboardAutoSyncDecision: Equatable {
    let shouldSend: Bool
    let reason: String
}

func evaluateClipboardAutoSync(
    pasteboard: NSPasteboard,
    autoSyncEnabled: Bool,
    featureAvailable: Bool,
    isConnected: Bool,
    lastChangeCount: Int,
    lastReceivedChangeCount: Int,
    lastAutoSentChangeCount: Int,
    lastSentText: String?,
    lastSentTime: TimeInterval,
    currentTime: TimeInterval
) -> (decision: ClipboardAutoSyncDecision, text: String?, html: String?, changeCount: Int) {
    let currentChangeCount = pasteboard.changeCount

    guard isConnected else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Not connected"), nil, nil, currentChangeCount)
    }
    guard autoSyncEnabled else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Auto-sync disabled"), nil, nil, currentChangeCount)
    }
    guard featureAvailable else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Clipboard feature unavailable"), nil, nil, currentChangeCount)
    }
    guard currentChangeCount != lastChangeCount else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Change count unchanged"), nil, nil, currentChangeCount)
    }
    guard currentChangeCount != lastReceivedChangeCount else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Echo loop prevented: received from Android"), nil, nil, currentChangeCount)
    }
    guard currentChangeCount != lastAutoSentChangeCount else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Already auto-sent for this change count"), nil, nil, currentChangeCount)
    }
    guard !pasteboardContainsConcealedType(pasteboard) else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Concealed or confidential pasteboard item"), nil, nil, currentChangeCount)
    }
    guard let text = pasteboard.string(forType: .string), !text.isEmpty else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "No text content"), nil, nil, currentChangeCount)
    }
    guard clipboardTextFits(text) else {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Content exceeds size limit"), nil, nil, currentChangeCount)
    }
    if let lastText = lastSentText, lastText == text, (currentTime - lastSentTime) < 5.0 {
        return (ClipboardAutoSyncDecision(shouldSend: false, reason: "Duplicate text within suppression window"), nil, nil, currentChangeCount)
    }

    let html = pasteboard.data(forType: .html).flatMap { String(data: $0, encoding: .utf8) }
    return (ClipboardAutoSyncDecision(shouldSend: true, reason: "Valid for auto-sync"), text, html, currentChangeCount)
}
